{
  "name": "@cortexkit/opencode-antigravity-auth",
  "version": "3.0.42",
  "description": "Google Antigravity OAuth auth plugin for OpenCode - access Gemini and Claude models using Google credentials",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "type": "module",
  "license": "MIT",
  "author": "CortexKit",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/cortexkit/antigravity-auth.git",
    "directory": "packages/opencode"
  },
  "homepage": "https://github.com/cortexkit/antigravity-auth#readme",
  "bugs": {
    "url": "https://github.com/cortexkit/antigravity-auth/issues"
  },
  "keywords": [
    "opencode",
    "google",
    "antigravity",
    "gemini",
    "oauth",
    "plugin",
    "auth",
    "claude"
  ],
  "engines": {
    "node": ">=20.0.0",
    "opencode": ">=1.18.4 <2 || >=2.0.22"
  },
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/types/src/server.d.ts",
      "import": "./dist/server.js"
    },
    "./tui": {
      "types": "./src/tui/entry.d.mts",
      "import": "./src/tui/entry.mjs"
    }
  },
  "files": [
    "dist/",
    "tui.js",
    "server.js",
    "src/tui.tsx",
    "src/tui/entry.mjs",
    "src/tui/entry.d.mts",
    "src/tui/command-dialogs.tsx",
    "src/tui/file-logger.ts",
    "src/tui-preferences.ts",
    "src/sidebar-state.ts",
    "src/rpc/rpc-client.ts",
    "src/rpc/rpc-dir.ts",
    "src/rpc/port-file.ts",
    "src/rpc/protocol.ts",
    "src/plugin/command-data.ts",
    "src/common-auth-embedded/",
    "src/tui-raw/",
    "src/tui-compiled/",
    "src/tui-ga-raw/",
    "src/tui-ga-compiled/",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "embed:check": "bun scripts/build-tui.ts --check",
    "build": "bun run embed:check && bun scripts/build-tui.ts --library && esbuild src/server.ts --bundle --platform=node --format=esm --external:zod --external:jsonc-parser --external:@cortexkit/private-files --external:@cortexkit/claustrum-client --external:@cortexkit/subc-client --outfile=dist/server.js --sourcemap --metafile=dist/server.meta.json --log-level=warning && tsc -p tsconfig.ga.emit.json && bun ../../scripts/finalize-declaration-specifiers.ts dist/types .",
    "build:tui": "bun run embed:check && bun scripts/build-tui.ts",
    "build:schema": "bun script/build-schema.ts",
    "build:settings-schema": "bun script/build-settings-schema.ts",
    "smoke:tui": "bun run embed:check && bun scripts/smoke-tui-pack-install.ts",
    "typecheck": "bun run embed:check && bun scripts/build-tui.ts --types && tsc --noEmit && tsc -p tsconfig.ga.json",
    "test": "bun run embed:check && bun test --isolate ./src ./scripts/build-tui.test.ts",
    "lint": "bun run embed:check && biome lint . --error-on-warnings",
    "format": "bun run embed:check && biome format --write .",
    "format:check": "bun run embed:check && biome format .",
    "prepack": "bun run embed:check && bun run build",
    "prepublishOnly": "bun run embed:check && bun run build",
    "test:e2e:models": "bun script/test-models.ts",
    "test:e2e:regression": "bun script/test-regression.ts"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*",
    "@opencode/plugin": ">=2.0.22",
    "@opentui/core": ">=0.4.5",
    "@opentui/keymap": ">=0.4.5",
    "@opentui/solid": ">=0.4.5",
    "solid-js": ">=1.9.0",
    "typescript": "^5 || ^6"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opencode/plugin": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/keymap": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    },
    "typescript": {
      "optional": true
    }
  },
  "devDependencies": {
    "@cortexkit/opencode-sidebar": "0.1.0",
    "@opencode-ai/sdk": "1.17.13",
    "@opencode/plugin": "2.0.22",
    "@opentui/core-ga": "npm:@opentui/core@0.5.14",
    "@opentui/solid-ga": "npm:@opentui/solid@0.5.14",
    "@types/json-schema": "7.0.15",
    "@types/node": "25.0.0",
    "esbuild": "^0.27.7",
    "solid-js-ga": "npm:solid-js@1.9.15",
    "zod-to-json-schema": "^3.25.1"
  },
  "dependencies": {
    "@cortexkit/claustrum-client": "0.18.0",
    "@cortexkit/subc-client": "0.24.0",
    "@cortexkit/antigravity-auth-core": "3.0.42",
    "@cortexkit/private-files": "0.2.2",
    "jsonc-parser": "^3.3.1",
    "xdg-basedir": "^5.1.0",
    "zod": "^4.0.0"
  },
  "bin": {
    "antigravity-auth": "./dist/cli.js"
  }
}
